CREATE INDEX users_name_trgm ON users USING gin (name gin_trgm_ops);

-- (A) 인덱스를 탑니다
SELECT * FROM users WHERE name LIKE '%kim%';

-- (B) 200만 행을 전부 읽고 정렬합니다
SELECT name FROM users ORDER BY name <-> 'kim' LIMIT 10;

CREATE INDEX events_tags_gin ON events USING gin (tags jsonb_path_ops);

-- 이 조건은 인덱스를 탑니다
EXPLAIN SELECT * FROM events WHERE tags @> '["urgent"]';
--  Bitmap Heap Scan on events
--    Recheck Cond: (tags @> '["urgent"]'::jsonb)
--    ->  Bitmap Index Scan on events_tags_gin

-- 이 조건만 Seq Scan입니다
EXPLAIN SELECT * FROM events WHERE tags ? 'urgent';
--  Seq Scan on events
--    Filter: (tags ? 'urgent'::text)
